/bin/bash -lc "python - <<'PY'
import csv, math
files=['97','98','99']
sets=[]
for s in files:
    path=f'codex_output/intermediate/res_{s}.tsv'
    ids=[]; up=[]; down=[]; na=0
    with open(path, newline='') as fh:
        for row in csv.DictReader(fh, delimiter='\\t'):
            ids.append(row['rowname'])
            try:
                lfc=float(row['log2FoldChange']); padj=float(row['padj'])
            except ValueError:
                na += 1; continue
            if math.isnan(lfc) or math.isnan(padj):
                na += 1; continue
            if padj < 0.05 and lfc > 1.5: up.append(row['rowname'])
            if padj < 0.05 and lfc < -1.5: down.append(row['rowname'])
    sets.append(set(ids))
    print(s, 'genes', len(ids), 'eligible_nonmissing', len(ids)-na, 'up', len(up), 'down', len(down))
print('identical_gene_sets', sets[0] == sets[1] == sets[2], 'shared', len(set.intersection(*sets)))
PY"

