import os, csv
from bioblend.galaxy import GalaxyInstance
with open(os.environ['GALAXY_API_KEY_FILE']) as fh: key=fh.read().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
results={
'97_up':'f9cad7b01a472135c0102772db566f51','97_down':'f9cad7b01a4721354c46afe118d90fbc',
'98_up':'f9cad7b01a472135434569e2b4a14293','98_down':'f9cad7b01a4721354a0fc93d8da7695f',
'99_up':'f9cad7b01a4721353ffc19968794bb6f','99_down':'f9cad7b01a47213592114832d41160a3'}
summaries={
'97_up':'f9cad7b01a472135c2ea9fa4a47eaa67','97_down':'f9cad7b01a47213522bab1c7796d0eb2',
'98_up':'f9cad7b01a47213570d396db7233b721','98_down':'f9cad7b01a472135af6f2e17294c046f',
'99_up':'f9cad7b01a472135fe56e22dfc500395','99_down':'f9cad7b01a472135911fe900a89b7528'}
for label,did in results.items():
    gi.datasets.download_dataset(did,file_path=f'codex_output/intermediate/ora_{label}.tsv',use_default_filename=False)
for label,did in summaries.items():
    gi.datasets.download_dataset(did,file_path=f'codex_output/intermediate/ora_{label}_summary.tsv',use_default_filename=False)

summary_data={}
for label in summaries:
    with open(f'codex_output/intermediate/ora_{label}_summary.tsv',newline='') as fh:
        summary_data[label]={r['metric']:r['value'] for r in csv.DictReader(fh,delimiter='\\t')}
print('mapping_hashes', sorted({x['mapping_hash'] for x in summary_data.values()}))
for label,x in summary_data.items():
    print(label,'input',x['foreground_input_genes'],'mapped',x['foreground_genes_in_universe'],'universe',x['universe_genes'],'hit_pathways',x['pathways_with_foreground_hits'],'adjusted',x['pathways_adjusted'])
sets={}
names={}
for label in results:
    sig=set()
    with open(f'codex_output/intermediate/ora_{label}.tsv',newline='') as fh:
        for r in csv.DictReader(fh,delimiter='\\t'):
            names[r['pathway_id']]=r['pathway_name']
            if float(r['adjusted_p_value']) < 0.05:
                sig.add(r['pathway_id'])
    sets[label]=sig
    print(label,'significant',len(sig),','.join(sorted(sig)))
up=sets['97_up'] & sets['98_up'] & sets['99_up']
down=sets['97_down'] & sets['98_down'] & sets['99_down']
combined=up|down
print('common_up',len(up),','.join(sorted(up)))
print('common_down',len(down),','.join(sorted(down)))
print('union_count',len(combined))
for pid in sorted(combined): print(pid, names[pid])
